import sqlite3
import string
import time
import urllib.parse
from typing import Optional, Union, Dict, Tuple

class URLShortenerService:
    BASE62_CHARS = string.digits + string.ascii_lowercase + string.ascii_uppercase

    def __init__(self, db_path: str = ":memory:") -> None:
        try:
            self.conn = sqlite3.connect(db_path, check_same_thread=False)
            self.conn.row_factory = sqlite3.Row
            self._create_tables()
        except Exception as e:
            print(f"Error initializing database: {e}")
            raise

    def _create_tables(self) -> None:
        with self.conn:
            self.conn.execute(
                """
                CREATE TABLE IF NOT EXISTS urls (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    original_url TEXT UNIQUE NOT NULL,
                    short_code TEXT UNIQUE NOT NULL,
                    created_at REAL NOT NULL
                )
                """
            )
            self.conn.execute(
                """
                CREATE TABLE IF NOT EXISTS analytics (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    short_code TEXT NOT NULL,
                    accessed_at REAL NOT NULL,
                    FOREIGN KEY(short_code) REFERENCES urls(short_code)
                )
                """
            )
            self.conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_urls_short_code ON urls(short_code)"
            )
            self.conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_urls_original_url ON urls(original_url)"
            )
            self.conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_analytics_short_code ON analytics(short_code)"
            )

    def _encode_base62(self, num: int) -> str:
        if num == 0:
            return self.BASE62_CHARS[0]
        base62 = []
        while num > 0:
            num, rem = divmod(num, 62)
            base62.append(self.BASE62_CHARS[rem])
        return "".join(reversed(base62))

    def _validate_url(self, url: str) -> bool:
        try:
            parsed = urllib.parse.urlparse(url)
            return bool(parsed.scheme and parsed.netloc)
        except Exception:
            return False

    def shorten_url(self, original_url: str) -> Dict[str, Union[bool, str]]:
        if not self._validate_url(original_url):
            return {"success": False, "error": "Invalid URL format"}

        try:
            with self.conn:
                cursor = self.conn.execute(
                    "SELECT short_code FROM urls WHERE original_url = ?", (original_url,)
                )
                row = cursor.fetchone()
                if row:
                    return {"success": True, "short_code": row["short_code"]}

                cursor = self.conn.execute(
                    "INSERT INTO urls (original_url, short_code, created_at) VALUES (?, '', ?)",
                    (original_url, time.time()),
                )
                row_id = cursor.lastrowid
                short_code = self._encode_base62(row_id)

                self.conn.execute(
                    "UPDATE urls SET short_code = ? WHERE id = ?", (short_code, row_id)
                )

            return {"success": True, "short_code": short_code}
        except Exception as e:
            return {"success": False, "error": str(e)}

    def redirect_url(self, short_code: str) -> Optional[str]:
        try:
            with self.conn:
                cursor = self.conn.execute(
                    "SELECT original_url FROM urls WHERE short_code = ?", (short_code,)
                )
                row = cursor.fetchone()
                if not row:
                    return None

                self.conn.execute(
                    "INSERT INTO analytics (short_code, accessed_at) VALUES (?, ?)",
                    (short_code, time.time()),
                )
                return row["original_url"]
        except Exception as e:
            print(f"Error redirecting URL: {e}")
            return None

    def get_analytics(self, short_code: str) -> Dict[str, Union[bool, int, str]]:
        try:
            with self.conn:
                cursor = self.conn.execute(
                    "SELECT original_url, created_at FROM urls WHERE short_code = ?", (short_code,)
                )
                url_row = cursor.fetchone()
                if not url_row:
                    return {"success": False, "error": "Short code not found"}

                cursor = self.conn.execute(
                    "SELECT COUNT(*) as click_count FROM analytics WHERE short_code = ?", (short_code,)
                )
                analytics_row = cursor.fetchone()
                click_count = analytics_row["click_count"] if analytics_row else 0

                return {
                    "success": True,
                    "short_code": short_code,
                    "original_url": url_row["original_url"],
                    "click_count": click_count,
                    "created_at": url_row["created_at"],
                }
        except Exception as e:
            return {"success": False, "error": str(e)}
